const b08RevisionEntries = `-- name: B08RevisionEntries :many
SELECT i.id, i.subscription_id, i.subject_revision, i.entry_key, i.identity_key, i.generation, i.legacy_position, i.route_id, i.route_revision, i.route_digest, i.route_json, i.credential_ref, i.expires_at, i.deadline, i.reserve_started, i.reservation_id, i.listener_id, i.endpoint_json, i.entry_id, i.identity_id, i.dispatch_epoch, i.task_id, i.state, i.revoked_at, i.cleanup_id, i.cleanup_epoch, i.cleanup_deadline, i.cleanup_task_id, i.cleanup_state, i.cleanup_generation FROM b08_revision_entries v JOIN b08_intents i ON i.id = v.intent_id
WHERE v.subscription_id = ? AND v.revision = ? ORDER BY v.position
`

type B08RevisionEntriesParams struct {
	SubscriptionID string
	Revision       int64
}

func (q *Queries) B08RevisionEntries(ctx context.Context, arg B08RevisionEntriesParams) ([]B08Intent, error) {
	rows, err := q.db.QueryContext(ctx, b08RevisionEntries, arg.SubscriptionID, arg.Revision)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []B08Intent
	for rows.Next() {
		var i B08Intent
		if err := rows.Scan(
			&i.ID,
			&i.SubscriptionID,
			&i.SubjectRevision,
			&i.EntryKey,
			&i.IdentityKey,
			&i.Generation,
			&i.LegacyPosition,
			&i.RouteID,
			&i.RouteRevision,
			&i.RouteDigest,
			&i.RouteJson,
			&i.CredentialRef,
			&i.ExpiresAt,
			&i.Deadline,
			&i.ReserveStarted,
			&i.ReservationID,
			&i.ListenerID,
			&i.EndpointJson,
			&i.EntryID,
			&i.IdentityID,
			&i.DispatchEpoch,
			&i.TaskID,
			&i.State,
			&i.RevokedAt,
			&i.CleanupID,
			&i.CleanupEpoch,
			&i.CleanupDeadline,
			&i.CleanupTaskID,
			&i.CleanupState,
			&i.CleanupGeneration,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

