const b08Work = `-- name: B08Work :many
SELECT id FROM b08_intents WHERE id > ?1 AND (
    state IN ('prepared', 'leased', 'committed', 'dispatching') OR cleanup_state = 'pending'
    OR (revoked_at IS NULL AND expires_at <= ?2)
) ORDER BY id LIMIT ?3
`

type B08WorkParams struct {
	AfterID  string
	Now      string
	PageSize int64
}

func (q *Queries) B08Work(ctx context.Context, arg B08WorkParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, b08Work, arg.AfterID, arg.Now, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
